# --------------------------------------------------------------------------
#  STORAN PROGRES BERSAMA (ganti Firebase)
#  Semua murid yang main melalui link yang sama berkongsi pelayan ini,
#  jadi guru boleh nampak progres semua murid secara live.
# --------------------------------------------------------------------------
PROGRESS = {}
_LOCK = threading.Lock()
CSV_FIELDS = ["id", "name", "classCode", "BILIK 1", "BILIK 2", "BILIK 3", "FINAL", "stars", "updatedAt"]


def _load_progress():
    if os.path.exists(SAVE_PATH):
        try:
            with open(SAVE_PATH, newline="", encoding="utf-8") as f:
                for row in csv.DictReader(f):
                    row["stars"] = int(row.get("stars") or 0)
                    PROGRESS[row["id"]] = row
        except Exception as e:
            print("Gagal baca fail progres:", e)


def _save_progress():
    try:
        tmp = SAVE_PATH + ".tmp"
        with open(tmp, "w", newline="", encoding="utf-8") as f:
            w = csv.DictWriter(f, fieldnames=CSV_FIELDS)
            w.writeheader()
            for r in PROGRESS.values():
                w.writerow({k: r.get(k, "") for k in CSV_FIELDS})
        os.replace(tmp, SAVE_PATH)
    except Exception as e:
        print("Gagal simpan progres:", e)


_load_progress()


def new_state():
    return {
        "id": None, "studentName": "", "classCode": "",
        "currentLevel": 0, "currentIndex": 0, "lives": 3, "stars": 0,
        "unlockedLevel": 0, "answersGiven": [],
        "completedRooms": [False, False, False], "finalCompleted": False,
        "targetCode": "", "inFinal": False, "finalIndex": 0, "finalAnswers": [],
        "roomScores": [0, 0, 0, 0]
    }


def ensure_scores(s):
    """Empat bilik x 25 markah; sentiasa cap pada 100."""
    if "roomScores" not in s:
        s["roomScores"] = [25 if done else 0 for done in s["completedRooms"]] + [25 if s["finalCompleted"] else 0]
    s["roomScores"] = [max(0, min(25, int(v))) for v in s["roomScores"][:4]]
    s["stars"] = min(100, sum(s["roomScores"]))
    return s


def reward_current_question(s, room, question_index):
    ensure_scores(s)
    # Soalan 1..5 setiap bilik; tidak boleh berganda apabila jawapan diulang.
    s["roomScores"][room] = max(s["roomScores"][room], min(25, (question_index + 1)*5))
    ensure_scores(s)


def restart_room_score(s, room):
    ensure_scores(s)
    s["roomScores"][room] = 0
    ensure_scores(s)


def sync_to_cloud(s):
    """Simpan progres murid ke storan bersama (sama seperti syncToCloud asal)."""
    ensure_scores(s)
    if not s["studentName"] or not s["classCode"]:
        return
    if not s["id"]:
        s["id"] = uuid.uuid4().hex[:12]
    rec = {
        "id": s["id"],
        "name": s["studentName"],
        "classCode": s["classCode"],
        "BILIK 1": "✅ Selesai" if s["completedRooms"][0] else "Sedang Dijawab",
        "BILIK 2": "✅ Selesai" if s["completedRooms"][1] else ("Sedang Dijawab" if s["unlockedLevel"] >= 1 else "—"),
        "BILIK 3": "✅ Selesai" if s["completedRooms"][2] else ("Sedang Dijawab" if s["unlockedLevel"] >= 2 else "—"),
        "FINAL": "🏆 MASTER" if s["finalCompleted"] else ("Sedang Dijawab" if s["unlockedLevel"] >= 3 else "Belum"),
        "stars": s["stars"],
        "updatedAt": datetime.now().strftime("%d/%m/%Y %H:%M:%S"),
    }
    with _LOCK:
        PROGRESS[s["id"]] = rec
        _save_progress()


