def normalize_input(x):
    return re.sub(r"\s+", "", str(x).lower()).replace(";", ",", 1)


def _num(v):
    return ("%g" % v) if isinstance(v, float) else str(v)


def is_correct(user, q):
    user = (user or "").strip()
    if not user:
        return False
    if isinstance(q["a"], (int, float)):
        try:
            return abs(float(user.replace(",", ".", 1)) - q["a"]) < 0.001
        except ValueError:
            return False
    nu, na = normalize_input(user), normalize_input(q["a"])
    if nu == na:
        return True
    if q.get("alt"):
        a1 = f"{_num(q['alt'][0])},{_num(q['alt'][1])}"
        return nu in (a1, f"({a1})")
    return False


def make_password(answers):
    parts = []
    for a in answers[:3]:
        if isinstance(a, (int, float)):
            parts.append(str(abs(round(a))))
        else:
            parts.append(re.sub(r"\D", "", str(a))[:2] or "7")
    return "-".join(parts), "".join(parts)


