#  SIJIL (gambar PNG)
# --------------------------------------------------------------------------
def _font(size, bold=False):
    candidates = []
    try:
        from matplotlib import font_manager
        candidates.append(font_manager.findfont(
            font_manager.FontProperties(family="DejaVu Sans", weight="bold" if bold else "normal")))
    except Exception:
        pass
    candidates += [
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf",
    ]
    for p in candidates:
        try:
            return ImageFont.truetype(p, size)
        except Exception:
            continue
    return ImageFont.load_default(size=size)


def make_certificate(name, stars):
    W, H = 1800, 1273
    img = Image.new("RGB", (W, H), (5, 12, 30))
    d = ImageDraw.Draw(img)

    cyan, gold, white, soft = (26, 229, 255), (255, 214, 10), (245,245,245), (149, 190, 255)

    for y in range(H):
        ratio = y / H
        r = int(5 + ratio * 6)
        g = int(12 + ratio * 16)
        b = int(30 + ratio * 28)
        d.line([(0, y), (W, y)], fill=(r, g, b))

    for x in range(0, W, 50):
        d.line([(x, 0), (x, H)], fill=(10, 32, 58))
    for y in range(0, H, 50):
        d.line([(0, y), (W, y)], fill=(10, 32, 58))

    for rad in range(360, 120, -30):
        d.ellipse([W//2-rad, 270-rad, W//2+rad, 270+rad], outline=(12, 58, 92), width=2)

    d.rounded_rectangle([40, 40, W-40, H-40], radius=34, outline=gold, width=8)
    d.rounded_rectangle([70, 70, W-70, H-70], radius=28, outline=cyan, width=3)
    d.rounded_rectangle([110, 110, W-110, H-110], radius=22, outline=(16, 54, 88), width=2)

    def c(text, y, font, fill):
        w = d.textlength(text, font=font)
        d.text(((W - w) / 2, y), text, font=font, fill=fill)

    c("★", 125, _font(120, True), gold)
    c("SIJIL PENCAPAIAN", 255, _font(88, True), gold)
    c("MATHVISION MASTER", 370, _font(34, True), cyan)
    c("Tahniah! Sijil ini dianugerahkan kepada:", 470, _font(38), white)

    # Nama sijil responsif: kecilkan tulisan sehingga muat dalam bingkai.
    # Jika nama masih terlalu panjang, balut mengikut perkataan dan pusatkan setiap baris.
    upper = re.sub(r"\s+", " ", (name or "Murid").strip()).upper()
    max_name_width = W - 320
    name_size = 86
    nf = _font(name_size, True)
    while name_size > 22 and d.textlength(upper, font=nf) > max_name_width:
        name_size -= 2
        nf = _font(name_size, True)

    name_lines = [upper]
    if d.textlength(upper, font=nf) > max_name_width:
        name_lines = []
        current = ""
        for word in upper.split():
            candidate = f"{current} {word}".strip()
            if current and d.textlength(candidate, font=nf) > max_name_width:
                name_lines.append(current)
                current = word
            else:
                current = candidate
        if current:
            name_lines.append(current)
        # Jaga-jaga untuk nama tanpa ruang yang sangat panjang.
        if any(d.textlength(line, font=nf) > max_name_width for line in name_lines):
            name_size = 20
            nf = _font(name_size, True)

    name_y = 555
    line_gap = max(34, name_size + 8)
    for line_index, name_line in enumerate(name_lines[:2]):
        c(name_line, name_y + line_index * line_gap, nf, white)
    underline_y = name_y + len(name_lines[:2]) * line_gap + 12
    nw = min(W - 260, max(560, max(d.textlength(line, font=nf) for line in name_lines[:2]) + 110))
    d.line([((W - nw) / 2, underline_y), ((W + nw) / 2, underline_y)], fill=gold, width=5)

    body_shift = max(0, underline_y - 675)
    c("Kerana telah berjaya menguasai topik Persamaan Linear", 740 + body_shift, _font(36), white)
    c("dan menyelesaikan pengembaraan MathVision dengan cemerlang", 790 + body_shift, _font(36), white)
    c("Pencapaian keseluruhan", 890 + body_shift, _font(34), soft)
    c(f"★ {min(100, max(0, stars))}% ★", 955 + body_shift, _font(70, True), cyan)
    c("Teruskan usaha dan jadilah peneroka matematik yang hebat!", 1060 + body_shift, _font(28), gold)
    c("✦ ✦ ✦", 1130 + body_shift, _font(44, True), cyan)

    safe = re.sub(r"[^A-Za-z0-9]+", "_", name).strip("_") or "Murid"
    path = os.path.join(OUT_DIR, f"Sijil_{safe}_{uuid.uuid4().hex[:6]}.png")
    img.save(path)
    return path



