HEAD = """
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css">
<script>
(function () {
  let ctx = null;
  window.playSound = function (type) {
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!ctx) ctx = new AC();
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator(), gain = ctx.createGain();
      osc.connect(gain); gain.connect(ctx.destination);
      const now = ctx.currentTime;
      const cfg = {
        click:   ['sine',     [[600,0]],                    0.2, 0.05],
        correct: ['triangle', [[440,0],[880,0.1]],          0.3, 0.3],
        wrong:   ['sawtooth', [[180,0],[110,0.15]],         0.3, 0.3],
        unlock:  ['sine',     [[523.25,0],[659.25,0.1],[783.99,0.2]], 0.3, 0.4]
      }[type];
      if (!cfg) return;
      osc.type = cfg[0];
      cfg[1].forEach(([f, t]) => osc.frequency.setValueAtTime(f, now + t));
      if (type === 'click') osc.frequency.exponentialRampToValueAtTime(200, now + 0.05);
      gain.gain.setValueAtTime(cfg[2], now);
      gain.gain.linearRampToValueAtTime(0.01, now + cfg[3]);
      osc.start(now); osc.stop(now + cfg[3]);
    } catch (e) {}
  };


 // ===== MUZIK LATAR MATHVISION: QUIZ GAME STYLE =====
 let musicOn = false;
 let musicCtx = null;
 let musicTimer = null;
 let musicStep = 0;

 // Muzik piano lembut (sintesis Web Audio, tidak perlu fail luar)
 const pianoMelody = [
   523.25,659.25,783.99,659.25,587.33,698.46,659.25,523.25,
   440.00,523.25,659.25,587.33,523.25,493.88,523.25,392.00
 ];
 function playPianoTone(freq, start, duration, volume) {
   if (!musicCtx) return;
   const gain = musicCtx.createGain();
   const filter = musicCtx.createBiquadFilter();
   filter.type = 'lowpass'; filter.frequency.value = 1900;
   gain.gain.setValueAtTime(0.0001, start);
   gain.gain.exponentialRampToValueAtTime(volume, start + 0.014);
   gain.gain.exponentialRampToValueAtTime(volume * .22, start + .20);
   gain.gain.exponentialRampToValueAtTime(0.0001, start + duration);
   filter.connect(gain); gain.connect(musicCtx.destination);
   [1,2,3].forEach((harmonic, i) => {
     const osc = musicCtx.createOscillator();
     const part = musicCtx.createGain();
     osc.type = 'sine'; osc.frequency.value = freq * harmonic;
     part.gain.value = [1,.19,.06][i];
     osc.connect(part); part.connect(filter);
     osc.start(start); osc.stop(start + duration + .02);
   });
 }
 function playQuizBeat() {
   if (!musicCtx || !musicOn) return;
   const now = musicCtx.currentTime;
   const note = pianoMelody[musicStep % pianoMelody.length];
   playPianoTone(note, now, .86, .105);
   if (musicStep % 4 === 0) playPianoTone(note / 2, now, 1.4, .05);
   musicStep++;
 }

 async function toggleMathVisionMusic() {
   const btn = document.getElementById("mv-music-toggle");
   if (!btn) return;

   const AC = window.AudioContext || window.webkitAudioContext;

   if (!AC) {
     btn.textContent = "Bunyi tidak disokong";
     return;
   }

   if (!musicCtx) musicCtx = new AC();

   if (!musicOn) {
     try {
       await musicCtx.resume();

       musicOn = true;
       musicStep = 0;
       btn.textContent = "🔇 Matikan Bunyi";

       playQuizBeat();
       musicTimer = setInterval(playQuizBeat, 650);
     } catch (error) {
       btn.textContent = "🔊 Klik untuk cuba bunyi";
     }
   } else {
     musicOn = false;
     clearInterval(musicTimer);
     musicTimer = null;

     await musicCtx.suspend();
     btn.textContent = "🔊 Bunyi Sahaja";
   }
 }

 document.addEventListener("click", function(event) {
   if (event.target.closest("#mv-music-toggle")) {
     toggleMathVisionMusic();
   }
 });


  function startBg() {
    if (document.getElementById('mv-bg')) return;
    const c = document.createElement('canvas');
    c.id = 'mv-bg';
    document.body.prepend(c);
    const g = c.getContext('2d');
    const syms = ['∑','∫','π','√x','∞','≈','x','y','≠','+','÷'];
    const cols = ['#00f3ff','#ff00a0','#ffd700'];
    let W, H, P = [];
    const rnd = (a, b) => a + Math.random() * (b - a);
    function resize() { W = c.width = innerWidth; H = c.height = innerHeight; }
    resize(); addEventListener('resize', resize);
    for (let i = 0; i < 65; i++) P.push({ x: rnd(0, W), y: rnd(0, H), s: rnd(12, 22), v: rnd(0.3, 1.2),
      a: rnd(0.2, 0.7), sym: syms[Math.floor(Math.random() * syms.length)], isSym: Math.random() > 0.4,
      col: cols[Math.floor(Math.random() * 3)] });
    (function draw() {
      g.fillStyle = '#030814'; g.fillRect(0, 0, W, H);
      g.strokeStyle = 'rgba(0,243,255,0.06)'; g.lineWidth = 1;
      for (let x = 0; x < W; x += 60) { g.beginPath(); g.moveTo(x, 0); g.lineTo(x, H); g.stroke(); }
      for (let y = 0; y < H; y += 60) { g.beginPath(); g.moveTo(0, y); g.lineTo(W, y); g.stroke(); }
      g.textAlign = 'center'; g.textBaseline = 'middle';
      for (const p of P) {
        p.y -= p.v; if (p.y < -20) { p.y = H + 20; p.x = rnd(0, W); }
        g.globalAlpha = p.a; g.fillStyle = p.col;
        if (p.isSym) { g.font = p.s + 'px sans-serif'; g.fillText(p.sym, p.x, p.y); }
        else { g.beginPath(); g.arc(p.x, p.y, p.s / 6, 0, Math.PI * 2); g.fill(); }
      }
      g.globalAlpha = 1;
      requestAnimationFrame(draw);
    })();
  }
  if (document.readyState !== 'loading') startBg(); else document.addEventListener('DOMContentLoaded', startBg);
})();
</script>
"""

