def dashboard_df(cls):
    with _LOCK:
        rows = [
            r.copy()
            for r in PROGRESS.values()
            if str(r.get("classCode", "")).strip().upper()
            == str(cls or "").strip().upper()
        ]

    rows.sort(key=lambda r: -int(r.get("stars") or 0))

    data = [
        [
            r.get("name", ""),
            r.get("classCode", ""),
            r.get("BILIK 1", "—"),
            r.get("BILIK 2", "—"),
            r.get("BILIK 3", "—"),
            r.get("FINAL", "Belum"),
            int(r.get("stars") or 0),
            str(r.get("updatedAt", "")).split(" ")[0],
        ]
        for r in rows
    ]

    return pd.DataFrame(data, columns=DASH_HEADERS)



